import MoneyField from '../../../components/Forms/MoneyField';
import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Grid,
  Stack,
  Typography,
  useMediaQuery,
} from '@mui/material';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useCustomerpayCreditMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import PaymentsIcon from '@mui/icons-material/Payments';
import PaymentsOutlinedIcon from '@mui/icons-material/PaymentsOutlined';
import ReceiptIcon from '@mui/icons-material/Receipt';
import { ICustomerDetailsData } from '../../../core/Interface/customer.interface';

interface INewCustomer {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: ICustomerDetailsData;
}

const NewCustomer = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
}: INewCustomer) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newCustomer, { isLoading }] = useCustomerpayCreditMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'category', 'customer']);
  const buttonText = data ? t('customer:title.pay') : t('common:create');
  const [paymentMethod, setPaymentMethod] = React.useState('Cash');

  const handleClose = () => {
    handleCloseDialog(false);
  };
  const customerId = data
    ? 'customerId' in data && data.customerId
      ? data.customerId
      : data.id
    : '';

  const formik = useFormik({
    initialValues: {
      customerId: customerId,
      amount: '',
      paymentMethod: 'Cash',
    },
    onSubmit: async (values) => {
      try {
        const temData = {
          ...(data ? { customerId: values.customerId } : {}),
          amount: values.amount,
          paymentMethod: values.paymentMethod,
        };

        const addCustomerResponse = await newCustomer(temData).unwrap();
        if (!addCustomerResponse.status) {
          showErrorMessage(addCustomerResponse.message);
        } else {
          showMessage(addCustomerResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const handleCardClick = (method: string) => {
    setPaymentMethod(method);
    formik.setFieldValue('paymentMethod', method);
  };

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="sm"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <PaymentsOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Process customer payment</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <Grid
              container
              justifyContent="space-between"
              mb={3}
            >
              <Grid
                item
                lg={3.7}
                md={3.8}
                onClick={() => handleCardClick('Cash')}
                sm={3.9}
                xs={3.9}
                {...formik.getFieldProps('paymentMethod')}
                sx={{
                  border: '2px solid #E6E8F3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                  borderRadius: 2,
                  backgroundColor:
                    paymentMethod === 'Cash'
                      ? appColors.reflexBlue[10]
                      : 'transparent',
                  '&:hover': {
                    backgroundColor: appColors.reflexBlue[10],
                    cursor: 'pointer',
                  },
                }}
              >
                <PaymentsIcon style={{ width: 50, height: 50 }} />
                <Typography sx={{ fontWeight: 500, fontSize: '1.2rem' }}>
                  Cash
                </Typography>
              </Grid>{' '}
              <Grid
                item
                lg={3.7}
                md={3.8}
                onClick={() => handleCardClick('Card')}
                sm={3.9}
                xs={3.9}
                {...formik.getFieldProps('paymentMethod')}
                sx={{
                  border: '2px solid #E6E8F3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                  borderRadius: 2,
                  backgroundColor:
                    paymentMethod === 'Card'
                      ? appColors.reflexBlue[10]
                      : 'transparent',
                  '&:hover': {
                    backgroundColor: appColors.reflexBlue[10],
                    cursor: 'pointer',
                  },
                }}
              >
                <CreditCardIcon style={{ width: 50, height: 50 }} />
                <Typography sx={{ fontWeight: 500, fontSize: '1.2rem' }}>
                  Card
                </Typography>
              </Grid>
              <Grid
                item
                lg={3.7}
                md={3.8}
                onClick={() => handleCardClick('Cheque')}
                sm={3.9}
                xs={3.9}
                {...formik.getFieldProps('paymentMethod')}
                sx={{
                  py: 1,
                  border: '2px solid #E6E8F3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                  borderRadius: 2,
                  backgroundColor:
                    paymentMethod === 'Cheque'
                      ? appColors.reflexBlue[10]
                      : 'transparent',
                  '&:hover': {
                    backgroundColor: appColors.reflexBlue[10],
                    cursor: 'pointer',
                  },
                }}
              >
                <ReceiptIcon style={{ width: 50, height: 50 }} />
                <Typography sx={{ fontWeight: 500, fontSize: '1.2rem' }}>
                  Cheque
                </Typography>
              </Grid>
            </Grid>
            <Grid container>
              <GridItem>
                <FieldHeader title="Amount" />
                <MoneyField
                  autoComplete="off"
                  placeholder="Amount"
                  size="small"
                  {...formik.getFieldProps('amount')}
                  sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                />
              </GridItem>
            </Grid>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                borderColor: '#CBD5E1',
                borderRadius: '8px',
                color: '#475569',
                fontWeight: 600,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{
                background: HEADER_GRADIENT,
                borderRadius: '8px',
                boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
                color: '#fff',
                fontWeight: 700,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { opacity: 0.9 },
                '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
              }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewCustomer);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
