import { Box } from '@mui/material';
import * as React from 'react';
import SalesDiscount from './SalesDiscount';
import AddMobile from './AddMobile';
import { addCustomer } from '../store/BasketSelector';
import { useSelector } from 'react-redux';
import PaymentMethodsModel from './Model/PaymentMethodsModel';

export interface SalesActionLeftHandle {
  pay: () => void;
  isLoading: boolean;
  openDiscount: () => void;
}

const SalesActionLeft = React.forwardRef<SalesActionLeftHandle, object>((_, ref) => {
  const customer = useSelector(addCustomer);
  const [openDiscount, setOpenDiscount] = React.useState(false);
  const [openAddMobile, setOpenAddMobile] = React.useState(false);
  const [openPaymentDialog, setOpenPaymentDialog] = React.useState(false);

  const pay = () => {
    if (!customer.mobile || !customer.customerName) {
      setOpenAddMobile(true);
    } else {
      setOpenPaymentDialog(true);
    }
  };

  React.useImperativeHandle(ref, () => ({
    pay,
    isLoading: false,
    openDiscount: () => setOpenDiscount(true),
  }));

  return (
    <Box>
      {openDiscount && (
        <SalesDiscount
          handleCloseDialog={() => setOpenDiscount(false)}
          openModel={openDiscount}
          title="Add Discount"
        />
      )}

      {openAddMobile && (
        <AddMobile
          customers=""
          handleCloseDialog={() => setOpenAddMobile(false)}
          openModel={openAddMobile}
          title="Add Customer"
        />
      )}

      <PaymentMethodsModel
        handleClose={() => setOpenPaymentDialog(false)}
        open={openPaymentDialog}
      />
    </Box>
  );
});

SalesActionLeft.displayName = 'SalesActionLeft';

export default SalesActionLeft;
