import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  InputAdornment,
  Skeleton,
  Slide,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { useVirtualizer } from '@tanstack/react-virtual';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { TransitionProps } from '@mui/material/transitions';
import { theme } from '../../../../../theme';
import SearchIcon from '@mui/icons-material/Search';
import InventoryIcon from '@mui/icons-material/Inventory2Outlined';
import { useGetAllInventoryQuery } from '../../../../posApi';
import { IInventoryDetails, IInventoryDetailsData } from '../../../../../core/Interface/inventory.interface';
import useSalesRich from '../../../useSalesRich';
import { HEADER_GRADIENT } from '../../../../../theme/appColors';

interface IStockModelPopup {
  open: boolean;
  handleClose: () => void;
}

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & { children: React.ReactElement<string, string> },
  ref: React.Ref<unknown>
) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const getStockStyle = (stock: number) => {
  if (stock <= 0) return { bg: '#FEF2F2', color: '#DC2626', label: 'Out of Stock' };
  if (stock <= 5) return { bg: '#FEF3C7', color: '#D97706', label: 'Low Stock' };
  return { bg: '#DCFCE7', color: '#16A34A', label: 'In Stock' };
};

const CARD_HEIGHT = 100; // px – approximate height of one product card
const ROW_GAP     = 12;  // px – gap between rows
const COL_GAP     = 12;  // px – gap between columns
const H_PADDING   = 20;  // px – horizontal padding on each side

interface ProductCardProps {
  item: IInventoryDetailsData;
  currencyCode: string;
}
const ProductCard: React.FC<ProductCardProps> = React.memo(({ item, currencyCode }) => {
  const stockStyle = getStockStyle(item.stockAvailable ?? 0);
  return (
    <Box
      sx={{
        background: '#fff',
        border: '1px solid #E2E8F0',
        borderRadius: '10px',
        display: 'flex',
        flexDirection: 'column',
        gap: 0.5,
        height: CARD_HEIGHT,
        p: 1.5,
        transition: 'box-shadow 0.16s, border-color 0.16s',
        '&:hover': {
          borderColor: '#0F8B8D',
          boxShadow: '0 4px 16px rgba(15,139,141,0.12)',
        },
      }}
    >
      <Typography
        sx={{
          color: '#0F1D4D',
          display: '-webkit-box',
          fontSize: '0.8rem',
          fontWeight: 700,
          lineHeight: 1.3,
          overflow: 'hidden',
          WebkitBoxOrient: 'vertical',
          WebkitLineClamp: 2,
        }}
      >
        {item.name}
      </Typography>

      <Typography sx={{ color: '#0F8B8D', fontSize: '0.86rem', fontWeight: 800 }}>
        {currencyCode} {Number(item.unitPrice).toFixed(2)}
      </Typography>

      <Box sx={{ mt: 'auto' }}>
        <Chip
          label={`${item.stockAvailable ?? 0} · ${stockStyle.label}`}
          size="small"
          sx={{
            background: stockStyle.bg,
            borderRadius: '5px',
            color: stockStyle.color,
            fontSize: '0.68rem',
            fontWeight: 700,
            height: 20,
          }}
        />
      </Box>
    </Box>
  );
});

// eslint-disable-next-line react/no-multi-comp
const StockModel: React.FC<IStockModelPopup> = ({ open, handleClose }) => {
  const { currencyCode } = useSalesRich();
  const inputRef   = useRef<HTMLInputElement>(null);
  const scrollRef  = useRef<HTMLDivElement>(null);
  const isMobile   = useMediaQuery(theme.breakpoints.down('md'));
  const isSmall    = useMediaQuery(theme.breakpoints.down('sm'));

  const [searchText, setSearchText] = useState('');

  const { data, isLoading, isFetching } = useGetAllInventoryQuery({
    pageIndex: 0,
    pageSize: 5000,
    searchText,
  });

  const records = useMemo(
    () => (data?.data as IInventoryDetails)?.records ?? [],
    [data?.data]
  );

  // Number of columns depends on breakpoint
  const cols = isSmall ? 2 : isMobile ? 3 : 4;

  // Group flat list into rows of `cols` items
  const rows = useMemo<IInventoryDetailsData[][]>(() => {
    const grouped: IInventoryDetailsData[][] = [];
    for (let i = 0; i < records.length; i += cols) {
      grouped.push(records.slice(i, i + cols));
    }
    return grouped;
  }, [records, cols]);

  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => CARD_HEIGHT + ROW_GAP,
    overscan: 6,
  });

  useEffect(() => {
    if (open) setTimeout(() => inputRef.current?.focus(), 150);
  }, [open]);

  const loading = isLoading || isFetching;

  return (
    <Dialog
      TransitionComponent={Transition}
      fullScreen={isMobile}
      fullWidth
      maxWidth="lg"
      onClose={handleClose}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: isMobile ? 0 : '12px',
          boxShadow: '0 24px 60px rgba(15,23,42,0.22)',
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
        },
      }}
    >
      {/* ── Header ──────────────────────────────────── */}
      <DialogTitle sx={{ background: HEADER_GRADIENT, flexShrink: 0, p: 0 }}>
        <Box sx={{ px: 3, pt: 2.5, pb: 0 }}>
          {/* Title row */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, mb: 2 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '10px',
                display: 'flex',
                flexShrink: 0,
                height: 40,
                justifyContent: 'center',
                width: 40,
              }}
            >
              <InventoryIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: 17, fontWeight: 800, lineHeight: 1.2 }}>
                Stock &amp; Price
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 11, fontWeight: 500 }}>
                {loading ? 'Loading…' : `${records.length.toLocaleString()} products`}
              </Typography>
            </Box>
          </Box>

          {/* Search */}
          <Box sx={{ pb: 2.5 }}>
            <TextField
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                  </InputAdornment>
                ),
              }}
              inputRef={inputRef}
              onKeyDown={(e) => {
                if (e.key === 'Enter') { e.preventDefault(); setSearchText(inputRef.current?.value ?? ''); }
              }}
              onChange={(e) => { if (e.target.value === '') setSearchText(''); }}
              placeholder="Search product name or code…"
              size="small"
              sx={{
                maxWidth: 480,
                width: '100%',
                '& .MuiOutlinedInput-root': {
                  background: 'rgba(255,255,255,0.12)',
                  borderRadius: '8px',
                  color: '#fff',
                  '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                  '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                  '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                  '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                },
              }}
              variant="outlined"
            />
          </Box>
        </Box>
      </DialogTitle>

      {/* ── Virtual scroll body ──────────────────────── */}
      <DialogContent sx={{ flex: 1, overflow: 'hidden', p: 0 }}>
        <Box
          ref={scrollRef}
          sx={{
            background: '#F4F5F7',
            height: isMobile ? '62vh' : '60vh',
            overflowY: 'auto',
            px: `${H_PADDING}px`,
            py: '16px',
          }}
        >
          {loading ? (
            /* Skeleton grid — matches real card layout */
            <Box
              sx={{
                display: 'grid',
                gap: `${ROW_GAP}px ${COL_GAP}px`,
                gridTemplateColumns: `repeat(${cols}, 1fr)`,
              }}
            >
              {Array.from({ length: cols * 6 }).map((_, i) => (
                <Skeleton key={i} height={CARD_HEIGHT} sx={{ borderRadius: '10px' }} variant="rectangular" />
              ))}
            </Box>
          ) : rows.length === 0 ? (
            <Box sx={{ alignItems: 'center', display: 'flex', flexDirection: 'column', gap: 1, justifyContent: 'center', minHeight: 200 }}>
              <InventoryIcon sx={{ color: '#CBD5E1', fontSize: 48 }} />
              <Typography sx={{ color: '#94A3B8', fontSize: '0.9rem', fontWeight: 500 }}>
                No products found
              </Typography>
            </Box>
          ) : (
            /* Virtual rows container */
            <Box sx={{ height: virtualizer.getTotalSize(), position: 'relative', width: '100%' }}>
              {virtualizer.getVirtualItems().map((virtualRow) => (
                <Box
                  key={String(virtualRow.key)}
                  style={{
                    position: 'absolute',
                    top: 0,
                    transform: `translateY(${virtualRow.start}px)`,
                    width: '100%',
                    display: 'grid',
                    gridTemplateColumns: `repeat(${cols}, 1fr)`,
                    gap: `${ROW_GAP}px ${COL_GAP}px`,
                    paddingBottom: `${ROW_GAP}px`,
                  }}
                >
                  {rows[virtualRow.index].map((item) => (
                    <ProductCard key={item.id} currencyCode={currencyCode} item={item} />
                  ))}
                </Box>
              ))}
            </Box>
          )}
        </Box>
      </DialogContent>

      {/* ── Footer ──────────────────────────────────── */}
      <DialogActions
        sx={{
          background: '#fff',
          borderTop: '1px solid #E2E8F0',
          flexShrink: 0,
          gap: 1.5,
          px: 3,
          py: 2,
        }}
      >
        <Button
          onClick={handleClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(StockModel);
