import { PayloadAction, createSlice } from '@reduxjs/toolkit';
import { IProductData } from '../../../core/Interface/product.interface';
import {
  IAddCount,
  IAddCustomer,
  IBasketState,
  IDiscount,
} from '../../../core/Interface/property.interface';

export interface BasketItem extends IProductData {
  count: number;
}

export interface BasketState {
  items: BasketItem[];
  discount?: number;
  discountAsPercentage?: boolean;
  finalSummaryStare?: boolean;
  mobile?: string;
  receivedAmount?: number;
  returnAmount?: number;
  customerName?: string;
  calculatedValue?: number;
  paymentMethod: string;
  balance: number;
  saleId?: string | null;
  customerId?: string;
}

const initialState: BasketState = {
  items: [],
  discount: 0,
  discountAsPercentage: false,
  finalSummaryStare: false,
  returnAmount: 0,
  paymentMethod: ' ',
  balance: 0,
  mobile: '',
  customerName: '',
  receivedAmount: 0,
  saleId: null,
   customerId: undefined, 
};

export const SalesRichBasket = createSlice({
  name: 'sales_rich_basket',
  initialState,
  reducers: {
    addItem: (state, action: PayloadAction<BasketItem>) => {
      let temItem = { ...action.payload };
      const findItem = state.items.find((element) => element.id === temItem.id);
      if (findItem) {
        if (temItem.isKgOrLitre) {
          const existingItem = state.items
            .map((item) => {
              if (item.id === temItem.id) {
                return { ...item, count: temItem.count };
              }
              return item;
            })
            .sort((a, b) =>
              a.id === temItem.id ? 1 : b.id === temItem.id ? -1 : 0
            );
          state.items = existingItem;
        } else {
          const existingItem = state.items
            .map((item) => {
              if (item.id === temItem.id) {
                return { ...item, count: item.count + 1 };
              }
              return item;
            })
            .sort((a, b) =>
              a.id === temItem.id ? 1 : b.id === temItem.id ? -1 : 0
            );
          state.items = existingItem;
        }
      } else {
        state.items.push(temItem);
      }
    },
    removeBasketItem: (state, action: PayloadAction<string>) => {
      const findItemIndex = state.items.findIndex(
        (element) => element.id === action.payload
      );
      if (findItemIndex > -1) {
        state.items.splice(findItemIndex, 1);
      }
    },
    removeBasket: (state) => {
      state = { ...initialState };
      return state;
    },
    updateBasketItem: (state, action: PayloadAction<IAddCount>) => {
      const { id, count, discountValue, isDiscountPercentage } = action.payload;
      const findItemIndex = state.items.findIndex(
        (element) => element.id === id
      );
      state.items[findItemIndex].count = count;
      state.items[findItemIndex].defaultDiscountAmount = discountValue;
      state.items[findItemIndex].isDiscountPercentage = isDiscountPercentage;
    },

    addDiscount: (state, action: PayloadAction<IDiscount>) => {
      state.discount = action.payload.discount;
      state.discountAsPercentage = action.payload.discountAsPercentage;
    },
    addFinalSummaryState: (state, action: PayloadAction<IBasketState>) => {
      state.finalSummaryStare = action.payload.finalSummaryStare;
    },
    addCustomerDetailes: (state, action: PayloadAction<IAddCustomer>) => {
      state.mobile = action.payload.mobile;
      state.customerName = action.payload.customerName;
      state.customerId = action.payload.id;
    },
    addReceivedMoney: (state, action: PayloadAction<number>) => {
      state.receivedAmount = action.payload;
    },
    addReturnAmount: (state, action: PayloadAction<number>) => {
      state.returnAmount = action.payload;
    },
    addPaymentMethod(state, action: PayloadAction<string>) {
      state.paymentMethod = action.payload;
    },
    addBalance(state, action: PayloadAction<number>) {
      state.balance = action.payload;
    },
    clearCustomer: (state) => {
      state.mobile = '';
      state.customerName = '';
      state.customerId = undefined;
    },
    setSaleDetail(state, action: PayloadAction<string | null>) {
      state.saleId = action.payload;
    },
    clearSaleId: (state) => {
      state.saleId = null;
    },
  },
});

export const {
  addItem,
  removeBasket,
  removeBasketItem,
  updateBasketItem,
  addDiscount,
  addReceivedMoney,
  addReturnAmount,
  addBalance,
  addCustomerDetailes,
  clearCustomer,
  setSaleDetail,
  clearSaleId,
} = SalesRichBasket.actions;

export const SalesRichBasketReducer = SalesRichBasket.reducer;

export { initialState as BasketInitialState };
