import React, { useState } from 'react';
import {
  Badge,
  Box,
  Divider,
  IconButton,
  Popover,
  Tooltip,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import NotificationsNoneIcon from '@mui/icons-material/NotificationsNone';
import NotificationsIcon from '@mui/icons-material/Notifications';
import WarningAmberRoundedIcon from '@mui/icons-material/WarningAmberRounded';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import PersonAddAltIcon from '@mui/icons-material/PersonAddAlt';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import AccountBalanceWalletOutlinedIcon from '@mui/icons-material/AccountBalanceWalletOutlined';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';

/* ── types ───────────────────────────────────────────────────────────────── */
interface PosNotification {
  id: number;
  icon: React.ReactNode;
  accent: string;
  title: string;
  body: string;
  time: string;
  read: boolean;
}

/* ── dummy data ──────────────────────────────────────────────────────────── */
const INITIAL_NOTIFICATIONS: PosNotification[] = [
  {
    id: 1,
    icon: <WarningAmberRoundedIcon sx={{ fontSize: 16 }} />,
    accent: '#DC2626',
    title: 'Low Stock Alert',
    body: 'Rice (5 kg) — only 3 units remaining. Reorder soon.',
    time: '2 min ago',
    read: false,
  },
  {
    id: 2,
    icon: <CheckCircleOutlineIcon sx={{ fontSize: 16 }} />,
    accent: '#059669',
    title: 'Sale Completed',
    body: 'Invoice #INV-0042 · LKR 4,850.00 received from Nimal Perera.',
    time: '18 min ago',
    read: false,
  },
  {
    id: 3,
    icon: <AccessTimeIcon sx={{ fontSize: 16 }} />,
    accent: '#D97706',
    title: 'Pre-Order Due Today',
    body: 'Order #PRE-1234 for Suresh Silva is scheduled for delivery today.',
    time: '1 hr ago',
    read: false,
  },
  {
    id: 4,
    icon: <PersonAddAltIcon sx={{ fontSize: 16 }} />,
    accent: '#2563EB',
    title: 'New Customer Registered',
    body: 'Kamani Fernando added as a new customer (0771234567).',
    time: '3 hr ago',
    read: true,
  },
  {
    id: 5,
    icon: <TrendingUpIcon sx={{ fontSize: 16 }} />,
    accent: '#0F8B8D',
    title: 'Daily Sales Update',
    body: "Today's sales: LKR 28,400.00 — 72% of your daily target reached.",
    time: '5 hr ago',
    read: true,
  },
  {
    id: 6,
    icon: <AccountBalanceWalletOutlinedIcon sx={{ fontSize: 16 }} />,
    accent: '#7C3AED',
    title: 'Outstanding Balance',
    body: 'Customer Rohan Mendis has an unpaid balance of LKR 1,500.00.',
    time: 'Yesterday',
    read: true,
  },
  {
    id: 7,
    icon: <Inventory2OutlinedIcon sx={{ fontSize: 16 }} />,
    accent: '#059669',
    title: 'Stock Received',
    body: 'Coconut Oil 1 L × 50 units added to inventory by Admin.',
    time: 'Yesterday',
    read: true,
  },
];

/* ── component ───────────────────────────────────────────────────────────── */
const NotificationBell: React.FC = () => {
  const [notifications, setNotifications] =
    useState<PosNotification[]>(INITIAL_NOTIFICATIONS);
  const [anchor, setAnchor] = useState<HTMLButtonElement | null>(null);

  const open       = Boolean(anchor);
  const unreadCount = notifications.filter((n) => !n.read).length;

  const handleOpen = (e: React.MouseEvent<HTMLButtonElement>) => {
    setAnchor(e.currentTarget);
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  };

  const handleClose = () => setAnchor(null);

  return (
    <>
      <Tooltip title="Notifications">
        <IconButton
          onClick={handleOpen}
          sx={{
            background: open ? alpha('#0F8B8D', 0.08) : 'transparent',
            borderRadius: '8px',
            color: open ? '#0F8B8D' : '#6B7280',
            flexShrink: 0,
            height: 36,
            width: 36,
            '&:hover': { background: '#F3F4F6' },
          }}
        >
          <Badge
            badgeContent={unreadCount}
            color="error"
            sx={{ '& .MuiBadge-badge': { fontSize: 9, height: 16, minWidth: 16 } }}
          >
            {open
              ? <NotificationsIcon sx={{ fontSize: 20 }} />
              : <NotificationsNoneIcon sx={{ fontSize: 20 }} />
            }
          </Badge>
        </IconButton>
      </Tooltip>

      <Popover
        anchorEl={anchor}
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        onClose={handleClose}
        open={open}
        PaperProps={{
          sx: {
            borderRadius: '12px',
            boxShadow: '0 8px 32px rgba(15,23,42,0.18)',
            mt: 1,
            overflow: 'hidden',
            width: 360,
          },
        }}
        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
      >
        {/* ── Header ──────────────────────────────────────────── */}
        <Box
          sx={{
            alignItems: 'center',
            background: 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)',
            display: 'flex',
            justifyContent: 'space-between',
            px: 2.5,
            py: 1.75,
          }}
        >
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
            <NotificationsIcon sx={{ color: '#fff', fontSize: 18 }} />
            <Typography sx={{ color: '#fff', fontSize: 14, fontWeight: 700 }}>
              Notifications
            </Typography>
          </Box>
        </Box>

        {/* ── List ────────────────────────────────────────────── */}
        <Box sx={{ maxHeight: 420, overflowY: 'auto' }}>
          {notifications.map((n, idx) => (
            <React.Fragment key={n.id}>
              {idx > 0 && <Divider sx={{ mx: 2 }} />}
              <Box
                sx={{
                  '&:hover': { background: '#F8FAFC' },
                  background: n.read ? '#fff' : alpha(n.accent, 0.04),
                  cursor: 'default',
                  display: 'flex',
                  gap: 1.5,
                  px: 2.5,
                  py: 1.5,
                  transition: 'background 0.12s',
                }}
              >
                {/* Icon bubble */}
                <Box
                  sx={{
                    alignItems: 'center',
                    background: alpha(n.accent, 0.12),
                    borderRadius: '8px',
                    color: n.accent,
                    display: 'flex',
                    flexShrink: 0,
                    height: 32,
                    justifyContent: 'center',
                    width: 32,
                  }}
                >
                  {n.icon}
                </Box>

                {/* Text */}
                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Box
                    sx={{
                      alignItems: 'center',
                      display: 'flex',
                      gap: 1,
                      justifyContent: 'space-between',
                    }}
                  >
                    <Typography
                      sx={{
                        color: '#111827',
                        fontSize: 12,
                        fontWeight: n.read ? 600 : 800,
                        lineHeight: 1.3,
                      }}
                    >
                      {n.title}
                    </Typography>
                    {!n.read && (
                      <Box
                        sx={{
                          background: '#DC2626',
                          borderRadius: '50%',
                          flexShrink: 0,
                          height: 7,
                          width: 7,
                        }}
                      />
                    )}
                  </Box>
                  <Typography
                    sx={{ color: '#6B7280', fontSize: 11, lineHeight: 1.4, mt: 0.25 }}
                  >
                    {n.body}
                  </Typography>
                  <Typography sx={{ color: '#9CA3AF', fontSize: 10, mt: 0.5 }}>
                    {n.time}
                  </Typography>
                </Box>
              </Box>
            </React.Fragment>
          ))}
        </Box>

        {/* ── Footer ──────────────────────────────────────────── */}
        <Box
          sx={{
            borderTop: '1px solid #F1F5F9',
            px: 2.5,
            py: 1.25,
            textAlign: 'center',
          }}
        >
          <Typography
            sx={{
              color: '#0F8B8D',
              cursor: 'pointer',
              fontSize: 12,
              fontWeight: 600,
              '&:hover': { color: '#0c7a7c' },
            }}
          >
            View all notifications
          </Typography>
        </Box>
      </Popover>
    </>
  );
};

export default React.memo(NotificationBell);
