import { PayloadAction, createSlice } from '@reduxjs/toolkit';
import {
  IAddCount,
  IAddCustomer,
  IBasketState,
  IDiscount,
} from '../../../core/Interface/property.interface';
import {
  BasketState,
  IPreOrderJewelleryBasketItem,
} from '../../../core/Interface/preOrderJewellery.interface';

const initialState: BasketState = {
  items: [],
  discount: 0,
  discountAsPercentage: false,
  finalSummaryStare: false,
  returnAmount: 0,
  paymentMethod: '',
  received: 0,
  deliveryDateTime: '',
  balance: 0,
};

export const basket = createSlice({
  name: 'jewelPreOrderBasket',
  initialState,
  reducers: {
    addItem: (state, action: PayloadAction<IPreOrderJewelleryBasketItem>) => {
      let temItem = { ...action.payload };
      const findItem = state.items.find((element) => element.id === temItem.id);
      if (findItem) {
        if (temItem.isKgOrLitre) {
          const existingItem = state.items
            .map((item) => {
              if (item.id === temItem.id) {
                return {
                  ...item,
                  count: temItem.count,
                  goldWeightQty: temItem.goldWeightQty,
                  goldWasteQty: temItem.goldWasteQty,
                  goldCarrot: temItem.goldCarrot,
                  makingCharge: temItem.makingCharge,
                  calculatedUnitPrice: temItem.calculatedUnitPrice,
                };
              }
              return item;
            })
            .sort((a, b) =>
              a.id === temItem.id ? 1 : b.id === temItem.id ? -1 : 0
            );
          state.items = existingItem;
        } else {
          const existingItem = state.items
            .map((item) => {
              if (item.id === temItem.id) {
                return {
                  ...item,
                  count: item.count + 1,
                  goldWeightQty: temItem.goldWeightQty ?? item.goldWeightQty,
                  goldWasteQty: temItem.goldWasteQty ?? item.goldWasteQty,
                  goldCarrot: temItem.goldCarrot ?? item.goldCarrot,
                  makingCharge: temItem.makingCharge ?? item.makingCharge,
                  calculatedUnitPrice:
                    temItem.calculatedUnitPrice ?? item.calculatedUnitPrice,
                };
              }
              return item;
            })
            .sort((a, b) =>
              a.id === temItem.id ? 1 : b.id === temItem.id ? -1 : 0
            );
          state.items = existingItem;
        }
      } else {
        state.items.push(temItem);
      }
    },
    editBasket: (
      state,
      action: PayloadAction<IPreOrderJewelleryBasketItem>
    ) => {
      const {
        id,
        goldWeightQty,
        goldWasteQty,
        goldCarrot,
        makingCharge,
        goldPrice8g,
      } = action.payload;
      const findItemIndex = state.items.findIndex(
        (element) => element.id === id
      );
      if (findItemIndex === -1) return;
      state.items[findItemIndex].goldWeightQty = goldWeightQty;
      state.items[findItemIndex].goldWasteQty = goldWasteQty;
      state.items[findItemIndex].goldCarrot = goldCarrot;
      state.items[findItemIndex].makingCharge = makingCharge;
      state.items[findItemIndex].goldPrice8g = goldPrice8g;
    },
    removeItem: (state, action: PayloadAction<string>) => {
      const findItemIndex = state.items.findIndex(
        (element) => element.id === action.payload
      );
      if (findItemIndex > -1) {
        state.items.splice(findItemIndex, 1);
      }
    },
    removeBasket: (state) => {
      return { ...initialState };
    },
    updateProductCount: (state, action: PayloadAction<IAddCount>) => {
      const { id, count, discountValue, isDiscountPercentage } = action.payload;
      const findItemIndex = state.items.findIndex(
        (element) => element.id === id
      );
      if (findItemIndex > -1) {
        state.items[findItemIndex].count = count;
        state.items[findItemIndex].defaultDiscountAmount = discountValue;
        state.items[findItemIndex].isDiscountPercentage = isDiscountPercentage;
      }
    },
    updateJewelleryItemDetails: (
      state,
      action: PayloadAction<{
        id: string;
        goldWeightQty: number;
        goldWasteQty: number;
        goldCarrot: string;
        makingCharge: number;
        calculatedUnitPrice: number;
      }>
    ) => {
      const {
        id,
        goldWeightQty,
        goldWasteQty,
        goldCarrot,
        makingCharge,
        calculatedUnitPrice,
      } = action.payload;
      const findItemIndex = state.items.findIndex(
        (element) => element.id === id
      );
      if (findItemIndex > -1) {
        state.items[findItemIndex].goldWeightQty = goldWeightQty;
        state.items[findItemIndex].goldWasteQty = goldWasteQty;
        state.items[findItemIndex].goldCarrot = goldCarrot;
        state.items[findItemIndex].makingCharge = makingCharge;
        state.items[findItemIndex].calculatedUnitPrice = calculatedUnitPrice;
      }
    },
    addDiscount: (state, action: PayloadAction<IDiscount>) => {
      state.discount = action.payload.discount;
      state.discountAsPercentage = action.payload.discountAsPercentage;
    },
    addFinalSummaryState: (state, action: PayloadAction<IBasketState>) => {
      state.finalSummaryStare = action.payload.finalSummaryStare;
    },
    addCustomerDetailes: (state, action: PayloadAction<IAddCustomer>) => {
      state.mobile = action.payload.mobile;
      state.customerName = action.payload.customerName;
      state.deliveryDateTime = action.payload.deliveryDateTime;
    },
    addReceivedMoney: (state, action: PayloadAction<number>) => {
      state.received = action.payload;
    },
    addReturnAmount: (state, action: PayloadAction<number>) => {
      state.returnAmount = action.payload;
    },
    addPaymentMethod(state, action: PayloadAction<string>) {
      state.paymentMethod = action.payload;
    },
    setReceivedAmount: (state, action) => {
      state.received = action.payload;
    },
    addBalance: (state, action) => {
      state.balance = action.payload;
    },
  },
});

export const {
  addItem,
  removeItem,
  removeBasket,
  updateProductCount,
  updateJewelleryItemDetails,
  addDiscount,
  addFinalSummaryState,
  addCustomerDetailes,
  addReceivedMoney,
  addReturnAmount,
  addPaymentMethod,
  editBasket,
  setReceivedAmount,
  addBalance,
} = basket.actions;

export const JewelPreOrderBasketReducer = basket.reducer;

export { initialState as BasketInitialState };
