import MoneyField from '../../../../components/Forms/MoneyField';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  IconButton,
  Slide,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useRef, useState } from 'react';
import { TransitionProps } from '@mui/material/transitions';
import { theme } from '../../../../theme';
import { appColors } from '../../../../theme/appColors';
import { PaymentType } from '../../../../core/types/commonType';
import { useGetUserQuery, useSaveSalesJewelleryMutation } from '../../../posApi';
import { useNotifier } from '../../../../core/Notifier';
import { useAppDispatch } from '../../../../store/hooks';
import { removeBasket } from '../../store/BasketSlice';
import AlertPopup1 from '../../../../components/ModelPopup/AlertPopup1';
import DateAlertPopup from '../../../../components/ModelPopup/DateAlertPopup';
import { Invoice } from '../Invoice';
import { IUserInfo } from '../../../../core/Interface/user.interface';
import { calculateFontSize, getPriceFormatWithoutCurrency } from '../../../../core/utils';
import { useReactToPrint } from 'react-to-print';
import { ISalesReceipt } from '../../../../core/Interface/sale.interface';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import CloseIcon from '@mui/icons-material/Close';
import LocalAtmIcon from '@mui/icons-material/LocalAtm';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import DescriptionOutlinedIcon from '@mui/icons-material/DescriptionOutlined';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import useSales from '../../useSales';
import PrePrintPopup from '../../../../components/ModelPopup/PrePrintPopup';

interface IPaymentEntry {
  id: number;
  type: string;
  cashAmount: string;
  cardAmount: string;
  cardLast4: string;
  chequeAmount: string;
  chequeNo: string;
}

interface Props {
  open: boolean;
  handleClose: () => void;
}

const inputFieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(appColors.white, 0.92),
    borderRadius: '4px',
    '& fieldset': { borderColor: alpha(appColors.blueGreyishLight[80], 0.16) },
    '&:hover fieldset': { borderColor: alpha('#2563EB', 0.28) },
    '&.Mui-focused': { boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.10)}` },
    '&.Mui-focused fieldset': { borderColor: '#2563EB' },
  },
};

const labelSx = { color: '#142352', fontSize: '0.82rem', fontWeight: 700, mb: 0.6 };

const PAYMENT_CONFIG = [
  { type: PaymentType.CACHE, label: 'Cash', icon: <LocalAtmIcon sx={{ fontSize: 20 }} />, accent: '#059669', bg: alpha('#059669', 0.07), border: alpha('#059669', 0.35) },
  { type: PaymentType.CARD, label: 'Card', icon: <CreditCardIcon sx={{ fontSize: 20 }} />, accent: '#2563EB', bg: alpha('#2563EB', 0.07), border: alpha('#2563EB', 0.35) },
  { type: PaymentType.CHEQUE, label: 'Cheque', icon: <DescriptionOutlinedIcon sx={{ fontSize: 20 }} />, accent: '#D97706', bg: alpha('#D97706', 0.07), border: alpha('#D97706', 0.35) },
];

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & { children: React.ReactElement<string, string> },
  ref: React.Ref<unknown>
) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const PaymentMethodsModel: React.FC<Props> = ({ open, handleClose }) => {
  const { calculateSummary, salesDetails } = useSales();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [saveSales, { isLoading }] = useSaveSalesJewelleryMutation();
  const [paymentList, setPaymentList] = useState<IPaymentEntry[]>([]);
  const { showErrorMessage, showMessage } = useNotifier();
  const dispatch = useAppDispatch();
  const [openAlert1, setOpenAlert1] = useState(false);
  const [openDateAlert, setOpenDateAlert] = useState(false);
  const [shouldPrint, setShouldPrint] = useState(false);
  const [openPrePrint, setOpenPrePrint] = useState(false);
  const [salesReceipt, setSalesReceipt] = useState<ISalesReceipt | null>(null);
  const { data: companyData } = useGetUserQuery();
  const componentRef = useRef<HTMLDivElement | null>(null);
  const userInfo = companyData?.data as IUserInfo;

  const printPaperSizeInPixel = React.useMemo(() => {
    if (userInfo?.branch?.printPaperSizeInPixel) return Number(userInfo.branch.printPaperSizeInPixel);
    return 10;
  }, [userInfo]);

  const handlePrint = useReactToPrint({ content: () => componentRef.current });

  useEffect(() => {
    if (open) {
      setPaymentList([{ id: Date.now(), type: PaymentType.CACHE, cashAmount: '', cardAmount: '', cardLast4: '', chequeAmount: '', chequeNo: '' }]);
      setSalesReceipt(null);
    }
  }, [open]);

  useEffect(() => {
    if (shouldPrint && componentRef.current) {
      handlePrint();
      setShouldPrint(false);
    }
  }, [shouldPrint, handlePrint]);

  const addPayment = (type: string) => {
    if (paymentList.some((p) => p.type === type)) return;
    setPaymentList((prev) => [...prev, { id: Date.now(), type, cashAmount: '', cardAmount: '', cardLast4: '', chequeAmount: '', chequeNo: '' }]);
  };

  const removePayment = (id: number) => setPaymentList((prev) => prev.filter((p) => p.id !== id));

  const updateField = (id: number, field: string, value: string) => {
    if (['cashAmount', 'cardAmount', 'chequeAmount'].includes(field)) {
      if (value.startsWith('-') || (!isNaN(parseFloat(value)) && parseFloat(value) < 0)) return;
    }
    setPaymentList((prev) => prev.map((p) => (p.id === id ? { ...p, [field]: value } : p)));
  };

  const hasType = (type: string) => paymentList.some((p) => p.type === type);

  const totalPaid = paymentList.reduce((sum, pay) => {
    return sum + parseFloat(pay.cashAmount || '0') + parseFloat(pay.cardAmount || '0') + parseFloat(pay.chequeAmount || '0');
  }, 0);

  const netTotal = calculateSummary.total;
  const balance = totalPaid - netTotal;

  const completeSale = async (settleDate?: string) => {
    try {
      const salesRes = await saveSales({
        ...salesDetails,
        paymentMethod: paymentList.map((p) => p.type).join(','),
        received: totalPaid,
        balance,
        isPaid: totalPaid >= netTotal,
        creditSettleDate: settleDate ?? null,
      }).unwrap();

      if (!salesRes.status) {
        showErrorMessage(salesRes.message);
        return;
      }

      const receipt = salesRes.data as ISalesReceipt;
      setSalesReceipt(receipt);
      dispatch(removeBasket());
      showMessage(salesRes.message);
      setTimeout(() => showMessage(''), 3000);
      setOpenAlert1(false);
      setOpenDateAlert(false);
      handleClose();

      if (userInfo?.company?.isSaleWhatsAppReceipt) {
        setOpenPrePrint(true);
      } else {
        setShouldPrint(true);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const paySale = async () => {
    if (balance < 0) {
      if (userInfo?.company?.isCreditPaymentDateOn) {
        setOpenDateAlert(true);
      } else {
        setOpenAlert1(true);
      }
      return;
    }
    await completeSale();
  };

  const canFinish = paymentList.some(
    (p) =>
      (p.type === PaymentType.CACHE && parseFloat(p.cashAmount || '0') > 0) ||
      (p.type === PaymentType.CARD && parseFloat(p.cardAmount || '0') > 0) ||
      (p.type === PaymentType.CHEQUE && parseFloat(p.chequeAmount || '0') > 0)
  );

  const balancePalette =
    balance >= 0
      ? { bg: alpha('#059669', 0.06), border: alpha('#059669', 0.18), color: '#065f46', muted: alpha('#059669', 0.8) }
      : { bg: alpha('#DC2626', 0.06), border: alpha('#DC2626', 0.18), color: '#991b1b', muted: alpha('#DC2626', 0.8) };

  return (
    <>
      <Dialog
        PaperProps={{
          sx: {
            background: 'linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(248,251,255,0.96) 100%)',
            border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
            borderRadius: isMobile ? 0 : '8px',
            boxShadow: '0 30px 80px rgba(15,23,42,0.28)',
            maxWidth: 'calc(100vw - 32px)',
            overflow: 'hidden',
            width: { xs: '100%', md: 620 },
          },
        }}
        TransitionComponent={Transition}
        fullScreen={isMobile}
        fullWidth
        maxWidth={false}
        onClose={handleClose}
        open={open}
      >
        {/* Header */}
        <DialogTitle sx={{ p: 0 }}>
          <Box sx={{
            background: 'linear-gradient(135deg, rgba(239,246,255,0.96) 0%, rgba(224,236,255,0.98) 54%, rgba(255,247,237,0.96) 100%)',
            borderBottom: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
            px: { xs: 2.5, md: 4 },
            py: { xs: 2.5, md: 3 },
          }}>
            <Box sx={{ alignItems: 'flex-start', display: 'flex', gap: 2, justifyContent: 'space-between' }}>
              <Box>
                <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.62), fontSize: '0.74rem', letterSpacing: '0.16em', mb: 0.9, textTransform: 'uppercase' }}>
                  Checkout
                </Typography>
                <Typography sx={{ color: '#142352', fontSize: { xs: '1.5rem', md: '1.9rem' }, fontWeight: 800, letterSpacing: '-0.5px', lineHeight: 1.1 }}>
                  {getPriceFormatWithoutCurrency(netTotal)}
                </Typography>
                <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.74), fontSize: '0.9rem', mt: 0.5 }}>
                  Net amount to collect
                </Typography>
              </Box>
              <IconButton
                onClick={handleClose}
                sx={{
                  backgroundColor: alpha(appColors.white, 0.72),
                  border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
                  color: alpha(appColors.blueGreyishLight[80], 0.72),
                  mr: -0.8, mt: -0.5,
                  '&:hover': { backgroundColor: alpha(appColors.white, 0.94) },
                }}
              >
                <CloseRoundedIcon />
              </IconButton>
            </Box>
          </Box>
        </DialogTitle>

        {/* Payment method selector */}
        <Box sx={{
          background: alpha('#2563EB', 0.03),
          borderBottom: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
          px: { xs: 2.5, md: 4 },
          py: 2,
        }}>
          <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.62), fontSize: '0.74rem', fontWeight: 700, letterSpacing: '0.14em', mb: 1.5, textTransform: 'uppercase' }}>
            Add Payment Method
          </Typography>
          <Stack direction="row" spacing={1.5}>
            {PAYMENT_CONFIG.map((cfg) => {
              const active = hasType(cfg.type);
              return (
                <Box
                  key={cfg.type}
                  onClick={() => !active && addPayment(cfg.type)}
                  sx={{
                    alignItems: 'center',
                    background: active ? cfg.bg : alpha(appColors.blueGreyishLight[80], 0.04),
                    border: `2px solid ${active ? cfg.border : alpha(appColors.blueGreyishLight[80], 0.16)}`,
                    borderRadius: '6px',
                    cursor: active ? 'default' : 'pointer',
                    display: 'flex',
                    flex: 1,
                    gap: 1,
                    opacity: active ? 1 : 0.75,
                    px: 1.5,
                    py: 1,
                    transition: 'all 0.15s',
                    '&:hover': { opacity: active ? 1 : 1 },
                  }}
                >
                  <Box sx={{ color: active ? cfg.accent : alpha(appColors.blueGreyishLight[80], 0.6) }}>
                    {cfg.icon}
                  </Box>
                  <Typography sx={{ color: active ? '#142352' : alpha(appColors.blueGreyishLight[80], 0.8), fontSize: '0.82rem', fontWeight: 700 }}>
                    {cfg.label}
                  </Typography>
                </Box>
              );
            })}
          </Stack>
        </Box>

        {/* Payment entries */}
        <DialogContent sx={{ p: 0 }}>
          <Box sx={{
            background: 'radial-gradient(circle at top right, rgba(37,99,235,0.04), transparent 28%), linear-gradient(180deg, rgba(255,255,255,0.92) 0%, rgba(248,251,255,0.88) 100%)',
            maxHeight: isMobile ? 'none' : '38vh',
            overflowY: 'auto',
            pb: 4, px: { xs: 2.5, md: 4 }, pt: 2.5,
          }}>
            <Stack spacing={2}>
              {paymentList.map((pay) => {
                const cfg = PAYMENT_CONFIG.find((c) => c.type === pay.type);
                return (
                  <Box key={pay.id} sx={{
                    background: cfg?.bg ?? alpha(appColors.blueGreyishLight[80], 0.04),
                    border: `1px solid ${cfg?.border ?? alpha(appColors.blueGreyishLight[80], 0.16)}`,
                    borderRadius: '8px',
                    boxShadow: '0 10px 24px rgba(15,23,42,0.04)',
                    p: 2, position: 'relative',
                  }}>
                    <Stack alignItems="center" direction="row" justifyContent="space-between" sx={{ mb: 1.5 }}>
                      <Stack alignItems="center" direction="row" spacing={1}>
                        <Box sx={{ color: cfg?.accent ?? '#142352' }}>{cfg?.icon}</Box>
                        <Typography sx={{ color: '#142352', fontSize: '0.9rem', fontWeight: 700 }}>
                          {pay.type} Payment
                        </Typography>
                      </Stack>
                      <IconButton
                        onClick={() => removePayment(pay.id)}
                        size="small"
                        sx={{ backgroundColor: alpha('#B42318', 0.08), border: `1px solid ${alpha('#B42318', 0.12)}`, color: '#B42318', '&:hover': { backgroundColor: alpha('#B42318', 0.14) } }}
                      >
                        <CloseIcon fontSize="small" />
                      </IconButton>
                    </Stack>

                    {pay.type === PaymentType.CACHE && (
                      <Box>
                        <Typography sx={labelSx}>Amount</Typography>
                        <MoneyField
                          autoFocus fullWidth size="small" sx={inputFieldSx} type="number"
                          inputProps={{ min: 0, step: 'any' }}
                          onChange={(e) => updateField(pay.id, 'cashAmount', e.target.value)}
                          value={pay.cashAmount || ''}
                        />
                      </Box>
                    )}
                    {pay.type === PaymentType.CARD && (
                      <Stack spacing={1.5}>
                        <Box>
                          <Typography sx={labelSx}>Amount</Typography>
                          <MoneyField fullWidth size="small" sx={inputFieldSx} type="number" inputProps={{ min: 0, step: 'any' }} onChange={(e) => updateField(pay.id, 'cardAmount', e.target.value)} value={pay.cardAmount || ''} />
                        </Box>
                        <Box>
                          <Typography sx={labelSx}>Last 4 Digits</Typography>
                          <TextField fullWidth size="small" sx={inputFieldSx} inputProps={{ inputMode: 'numeric' }} onChange={(e) => { let v = e.target.value.replace(/\D/g, ''); if (v.length > 4) v = v.slice(0, 4); updateField(pay.id, 'cardLast4', v); }} value={pay.cardLast4 || ''} />
                        </Box>
                      </Stack>
                    )}
                    {pay.type === PaymentType.CHEQUE && (
                      <Stack spacing={1.5}>
                        <Box>
                          <Typography sx={labelSx}>Amount</Typography>
                          <MoneyField fullWidth size="small" sx={inputFieldSx} type="number" inputProps={{ min: 0, step: 'any' }} onChange={(e) => updateField(pay.id, 'chequeAmount', e.target.value)} value={pay.chequeAmount || ''} />
                        </Box>
                        <Box>
                          <Typography sx={labelSx}>Cheque No</Typography>
                          <TextField fullWidth size="small" sx={inputFieldSx} type="number" inputProps={{ step: 'any' }} onChange={(e) => updateField(pay.id, 'chequeNo', e.target.value)} value={pay.chequeNo || ''} />
                        </Box>
                      </Stack>
                    )}
                  </Box>
                );
              })}
            </Stack>
          </Box>
        </DialogContent>

        {/* Balance bar */}
        <Box sx={{ background: balancePalette.bg, borderBottom: `1px solid ${balancePalette.border}`, borderTop: `1px solid ${balancePalette.border}`, px: { xs: 2.5, md: 4 }, py: 1.5 }}>
          <Stack alignItems="center" direction="row" justifyContent="space-between">
            <Box>
              <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.72), fontSize: '0.7rem', fontWeight: 600, letterSpacing: '1px', textTransform: 'uppercase' }}>Total Paid</Typography>
              <Typography sx={{ color: '#142352', fontSize: '1.1rem', fontWeight: 700 }}>{getPriceFormatWithoutCurrency(totalPaid)}</Typography>
            </Box>
            <Divider flexItem orientation="vertical" sx={{ mx: 2 }} />
            <Box sx={{ flex: 1 }}>
              {balance === 0 && (
                <Stack alignItems="center" direction="row" spacing={0.8}>
                  <CheckCircleOutlineIcon sx={{ color: '#059669', fontSize: 17 }} />
                  <Typography sx={{ color: '#065f46', fontSize: '0.88rem', fontWeight: 700 }}>Paid in full</Typography>
                </Stack>
              )}
              {balance > 0 && (
                <>
                  <Typography sx={{ color: balancePalette.muted, fontSize: '0.7rem', fontWeight: 600, letterSpacing: '1px', textTransform: 'uppercase' }}>Change</Typography>
                  <Stack alignItems="center" direction="row" spacing={0.8}>
                    <InfoOutlinedIcon sx={{ color: balancePalette.color, fontSize: 16 }} />
                    <Typography sx={{ color: balancePalette.color, fontSize: '0.96rem', fontWeight: 700 }}>{getPriceFormatWithoutCurrency(balance)}</Typography>
                  </Stack>
                </>
              )}
              {balance < 0 && (
                <>
                  <Typography sx={{ color: balancePalette.muted, fontSize: '0.7rem', fontWeight: 600, letterSpacing: '1px', textTransform: 'uppercase' }}>Amount Due</Typography>
                  <Stack alignItems="center" direction="row" spacing={0.8}>
                    <ErrorOutlineIcon sx={{ color: balancePalette.color, fontSize: 16 }} />
                    <Typography sx={{ color: balancePalette.color, fontSize: '0.96rem', fontWeight: 700 }}>{getPriceFormatWithoutCurrency(Math.abs(balance))}</Typography>
                  </Stack>
                </>
              )}
            </Box>
          </Stack>
        </Box>

        {/* Footer */}
        <DialogActions sx={{ p: 0 }}>
          <Box sx={{
            alignItems: { xs: 'stretch', md: 'center' },
            backgroundColor: alpha('#F8FAFC', 0.94),
            borderTop: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.08)}`,
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            px: { xs: 2.5, md: 4 },
            py: 2.3,
            width: '100%',
          }}>
            <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.74), fontSize: '0.84rem', lineHeight: 1.6 }}>
              Select a payment method and enter the amount.
            </Typography>
            <Box sx={{ display: 'flex', flexDirection: { xs: 'column-reverse', sm: 'row' }, gap: 1.5, width: { xs: '100%', md: 'auto' } }}>
              <Button
                disabled={isLoading}
                onClick={handleClose}
                sx={{ borderColor: alpha('#142352', 0.22), borderRadius: '4px', color: '#142352', fontWeight: 700, height: 46, minWidth: 130, px: 3, textTransform: 'none' }}
                variant="outlined"
              >
                Cancel
              </Button>
              <Button
                autoFocus
                disabled={isLoading || !canFinish}
                onClick={paySale}
                startIcon={isLoading ? <CircularProgress size={14} sx={{ color: 'inherit' }} /> : undefined}
                sx={{
                  background: 'linear-gradient(135deg, #059669 0%, #047857 100%)',
                  borderRadius: '4px',
                  boxShadow: '0 12px 24px rgba(5,150,105,0.22)',
                  fontWeight: 700,
                  height: 46,
                  minWidth: 160,
                  px: 3,
                  textTransform: 'none',
                  '&:hover': { background: 'linear-gradient(135deg, #047857 0%, #065f46 100%)' },
                  '&.Mui-disabled': { background: '#cbd5e1', boxShadow: 'none', color: '#64748b' },
                }}
                type="button"
                variant="contained"
              >
                Finish &amp; Pay
              </Button>
            </Box>
          </Box>
        </DialogActions>
      </Dialog>

      {/* Hidden print target */}
      {salesReceipt && (
        <Box sx={{ display: 'none' }}>
          <Invoice
            fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
            fontWeight={calculateFontSize(printPaperSizeInPixel).fontWeight}
            label={calculateFontSize(printPaperSizeInPixel).label}
            ref={componentRef}
            salesRes={salesReceipt}
            width={printPaperSizeInPixel}
          />
        </Box>
      )}

      {openPrePrint && salesReceipt && (
        <PrePrintPopup
          handleClose={() => setOpenPrePrint(false)}
          handlePrint={handlePrint}
          open={openPrePrint}
          whatsappLink={salesReceipt.whatsAppShareLink}
        >
          <Invoice
            fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
            fontWeight={calculateFontSize(printPaperSizeInPixel).fontWeight}
            label={calculateFontSize(printPaperSizeInPixel).label}
            ref={componentRef}
            salesRes={salesReceipt}
            width={printPaperSizeInPixel}
          />
        </PrePrintPopup>
      )}

      {openAlert1 && (
        <AlertPopup1
          handleCloseDialog={() => setOpenAlert1(false)}
          handlePay={completeSale}
          open={openAlert1}
          openModel={openAlert1}
          received={totalPaid}
          total={netTotal}
        />
      )}

      {openDateAlert && (
        <DateAlertPopup
          handleCloseDialog={() => setOpenDateAlert(false)}
          handlePay={completeSale}
          openModel={openDateAlert}
        />
      )}
    </>
  );
};

export default React.memo(PaymentMethodsModel);
